    fn __expected_tokens(__state: usize) -> Vec<::std::string::String> {
        const __TERMINAL: &'static [&'static str] = &[
            r###""!=""###,
            r###""%""###,
            r###""(""###,
            r###"")""###,
            r###""*""###,
            r###""+""###,
            r###"",""###,
            r###""-""###,
            r###""--""###,
            r###""->""###,
            r###"".""###,
            r###""/""###,
            r###"":""###,
            r###"";""###,
            r###""<""###,
            r###""<=""###,
            r###""=""###,
            r###""==""###,
            r###"">""###,
            r###"">=""###,
            r###""Edge""###,
            r###""False""###,
            r###""Graph""###,
            r###""Node""###,
            r###""NodeType""###,
            r###""True""###,
            r###""and""###,
            r###""filter""###,
            r###""for""###,
            r###""ident""###,
            r###""in""###,
            r###""merge""###,
            r###""not""###,
            r###""number""###,
            r###""or""###,
            r###""short_dist""###,
            r###""string""###,
            r###""{""###,
            r###""|""###,
            r###""}""###,
        ];
        __ACTION[(__state * 40)..].iter().zip(__TERMINAL).filter_map(|(&state, terminal)| {
            if state == 0 {
                None
            } else {
                Some(terminal.to_string())
            }
        }).collect()
    }
